            className="hidden"
            onChange={(e) => { void handleFile(e.target.files?.[0]); e.target.value = ""; }}
          />
        </div>
        <p className="mt-3 text-sm leading-relaxed text-muted-foreground">{t("scratch.prompt")}</p>

