                        <MessageSquareText className="h-2.5 w-2.5" />
                        {item.comment_count}
                      </span>
                    )}
                    <span className="shrink-0 text-[10px] tabular-nums text-muted-foreground/50">{item.last_read_at.slice(5, 10)}</span>
                  </button>
                );
              })}
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

